<?php
/** AI agents: workflows vs agents, the agent loop, tool design, MCP, safety and permissions, evaluating agents. */

return [
    'id' => 'ai-agents', 'family' => 'llm', 'after' => 'llm-api',
    'title' => L('Agenti AI e MCP', 'AI Agents and MCP'), 'short' => L('Agenti AI', 'AI Agents'), 'level' => L('Avanzato', 'Advanced'),
    'desc' => L('Modelli che agiscono: flussi o agenti, il ciclo agentico, progettare gli strumenti, il Model Context Protocol, sicurezza e permessi, valutazione.', 'Models that act: workflows or agents, the agent loop, designing tools, the Model Context Protocol, safety and permissions, evaluation.'),
    'lessons' => [
        lesson('what', L('Flussi e agenti', 'Workflows and agents'), [
            P('Un **flusso** (workflow) è una sequenza di passi decisa dal tuo codice: “estrai, poi classifica, poi scrivi”. Un **agente** invece decide da solo quali strumenti usare e quando fermarsi, in un ciclo, per raggiungere un obiettivo.', 'A **workflow** is a sequence of steps decided by your code: “extract, then classify, then write”. An **agent** instead decides by itself which tools to use and when to stop, in a loop, to reach a goal.'),
            P('Gli agenti sono potenti per compiti aperti e difficili da prevedere (correggere un bug in un progetto, fare una ricerca), ma costano di più, sono più lenti e più difficili da controllare. Regola pratica: parti dalla soluzione **più semplice** (una chiamata, poi un flusso) e passa all’agente solo se serve davvero.', 'Agents are powerful for open-ended, hard-to-predict tasks (fixing a bug in a project, doing research), but they cost more, are slower and harder to control. Rule of thumb: start with the **simplest** solution (one call, then a workflow) and move to an agent only when you truly need one.'),
        ], [
            Q('w1', L('Chi decide i passi in un workflow?', 'Who decides the steps in a workflow?'), [L('Il tuo codice', 'Your code'), L('Il modello', 'The model'), L('L’utente a ogni passo', 'The user at each step'), L('Nessuno', 'Nobody')], 0, L('Nell’agente li decide il modello.', 'In an agent the model decides.')),
            Q('w2', L('Quando ha senso un agente?', 'When does an agent make sense?'), [L('Per compiti aperti e difficili da prevedere', 'For open-ended, hard-to-predict tasks'), L('Per tradurre una parola', 'To translate one word'), L('Sempre', 'Always'), L('Mai', 'Never')], 0, L('Altrimenti basta un flusso.', 'Otherwise a workflow is enough.')),
            Q('w3', L('Da dove conviene partire?', 'Where should you start?'), [L('Dalla soluzione più semplice', 'From the simplest solution'), L('Dall’agente più complesso', 'From the most complex agent'), L('Da dieci agenti insieme', 'From ten agents at once'), L('Dal fine-tuning', 'From fine-tuning')], 0, L('Complessità solo se serve.', 'Complexity only when needed.')),
        ], task('text', L('Per ciascun compito scrivi `flusso` o `agente`, uno per riga come `compito: scelta`. Compiti: `tradurre 1000 descrizioni prodotto`, `correggere un bug sconosciuto in un repository`.', 'For each task write `workflow` or `agent`, one per line as `task: choice`. Tasks: `translate 1000 product descriptions`, `fix an unknown bug in a repository`.'), '', [re('(tradurre|translate)[^:\n]*:\s*(flusso|workflow)', L('La traduzione in serie è un flusso', 'Bulk translation is a workflow')), re('(bug)[^:\n]*:\s*(agente|agent)', L('Il bug sconosciuto richiede un agente', 'The unknown bug needs an agent'))], '', "tradurre 1000 descrizioni prodotto: flusso\ncorreggere un bug sconosciuto in un repository: agente"), [
            dMatch(pMatch(), [[L('Una chiamata', 'One call'), L('Compiti semplici', 'Simple tasks')], [L('Flusso', 'Workflow'), L('Passi decisi dal codice', 'Steps decided by code')], [L('Agente', 'Agent'), L('Il modello sceglie gli strumenti', 'The model picks the tools')], [L('Costo', 'Cost'), L('Cresce con l’autonomia', 'Grows with autonomy')]], L('Scegliere il livello giusto.', 'Picking the right level.')),
            dFlash(pFlash(), [[L('Un agente decide quando fermarsi', 'An agent decides when to stop'), true], [L('Gli agenti sono sempre più economici', 'Agents are always cheaper'), false], [L('Un flusso ha passi decisi dal codice', 'A workflow has code-decided steps'), true], [L('Ogni problema richiede un agente', 'Every problem needs an agent'), false]], L('Semplice prima, autonomo poi.', 'Simple first, autonomous later.')),
        ]),
        lesson('loop', L('Il ciclo agentico', 'The agent loop'), [
            P('Un agente è un ciclo: mandi al modello obiettivo, storia e strumenti; se chiede uno strumento lo esegui e rimandi il risultato; ripeti finché il modello risponde senza chiedere altro. Serve sempre un **limite** di passi o di spesa.', 'An agent is a loop: send the model goal, history and tools; if it asks for a tool, run it and send back the result; repeat until the model answers without asking for more. You always need a **limit** on steps or spending.'),
            C('messaggi = [{"role": "user", "content": obiettivo}]
for passo in range(20):                       # limite di sicurezza
    r = client.messages.create(model="claude-opus-5-5", max_tokens=4096,
                               tools=strumenti, messages=messaggi)
    messaggi.append({"role": "assistant", "content": r.content})
    if r.stop_reason != "tool_use":
        break                                 # risposta finale
    risultati = [{"type": "tool_result", "tool_use_id": b.id, "content": esegui(b.name, b.input)}
                 for b in r.content if b.type == "tool_use"]
    messaggi.append({"role": "user", "content": risultati})', 'python'),
            P('Il modello può chiedere più strumenti nello stesso turno: si eseguono tutti e si rimandano tutti i risultati in un solo messaggio. Gli SDK offrono anche helper che gestiscono il ciclo al posto tuo.', 'The model can ask for several tools in the same turn: run them all and send all the results back in one message. SDKs also offer helpers that run the loop for you.'),
        ], [
            Q('l1', L('Quando finisce il ciclo?', 'When does the loop end?'), [L('Quando il modello non chiede più strumenti', 'When the model stops asking for tools'), L('Dopo un passo, sempre', 'After one step, always'), L('Mai', 'Never'), L('Quando l’utente spegne il PC', 'When the user turns off the PC')], 0, L('O quando scatta il limite.', 'Or when the limit trips.')),
            Q('l2', L('Perché serve un limite di passi?', 'Why do you need a step limit?'), [L('Per evitare cicli infiniti e spese', 'To avoid endless loops and spending'), L('Per far contento il modello', 'To please the model'), L('Non serve', 'It is not needed'), L('Per l’estetica', 'For looks')], 0, L('Sicurezza prima di tutto.', 'Safety first.')),
            Q('l3', L('Come rimandi più risultati di strumenti?', 'How do you send back several tool results?'), [L('Tutti insieme in un solo messaggio', 'All together in one message'), L('Uno per chiamata separata', 'One per separate call'), L('Non si rimandano', 'You do not'), L('Solo il primo', 'Only the first')], 0, L('Ognuno con il suo tool_use_id.', 'Each with its tool_use_id.')),
        ], task('python', L('Completa il ciclo: esci con `break` quando `r.stop_reason` è diverso da `"tool_use"`.', 'Complete the loop: exit with `break` when `r.stop_reason` differs from `"tool_use"`.'), "for passo in range(20):\n    r = client.messages.create(model=\"claude-opus-5-5\", max_tokens=4096, tools=strumenti, messages=messaggi)\n    messaggi.append({\"role\": \"assistant\", \"content\": r.content})\n    ", [re('if\s+r\.stop_reason\s*!=\s*["\']tool_use["\']\s*:\s*\n\s+break', L('Esci alla risposta finale', 'You exit at the final answer')), re('for\s+passo\s+in\s+range\s*\(\s*20\s*\)', L('C’è il limite di passi', 'The step limit is there'))], '', "for passo in range(20):\n    r = client.messages.create(model=\"claude-opus-5-5\", max_tokens=4096, tools=strumenti, messages=messaggi)\n    messaggi.append({\"role\": \"assistant\", \"content\": r.content})\n    if r.stop_reason != \"tool_use\":\n        break"), [
            dOrder(pSort(), [L('Invia obiettivo e strumenti', 'Send goal and tools'), L('Il modello chiede uno strumento', 'The model asks for a tool'), L('Esegui lo strumento', 'Run the tool'), L('Rimanda il risultato', 'Send back the result'), L('Ripeti finché arriva la risposta finale', 'Repeat until the final answer')], L('Il cuore di un agente.', 'The heart of an agent.')),
            dBug(pBug(), ['while True:', '    r = client.messages.create(model=M, max_tokens=4096, tools=T, messages=msgs)', '    if r.stop_reason != "tool_use":', '        break'], 0, 'for passo in range(20):', L('Senza limite il ciclo può non finire mai.', 'Without a limit the loop may never end.')),
        ]),
        lesson('tools', L('Progettare gli strumenti', 'Designing tools'), [
            P('La qualità di un agente dipende molto dagli **strumenti**. Pochi strumenti chiari battono tanti strumenti confusi. Ogni strumento ha un nome parlante, una **descrizione** che dice cosa fa, quando usarlo e cosa restituisce, e uno schema di input preciso.', 'An agent’s quality depends heavily on its **tools**. A few clear tools beat many confusing ones. Each tool has a telling name, a **description** saying what it does, when to use it and what it returns, and a precise input schema.'),
            C('{
  "name": "cerca_ordini",
  "description": "Cerca gli ordini di un cliente per email. Usalo quando l’utente chiede lo stato di un ordine. Restituisce al massimo 10 ordini, dal più recente, con id, data, stato e totale.",
  "input_schema": {
    "type": "object",
    "properties": {
      "email": {"type": "string", "description": "Email del cliente"},
      "stato": {"type": "string", "enum": ["tutti", "aperti", "spediti"]}
    },
    "required": ["email"]
  }
}', 'json'),
            P('I risultati devono essere **brevi e utili**: niente dump di migliaia di righe, che riempiono il contesto. In caso di errore, restituisci un messaggio che aiuti il modello a correggersi (“email non valida: usa il formato nome@dominio”).', 'Results must be **short and useful**: no dumps of thousands of lines that fill the context. On error, return a message that helps the model fix itself (“invalid email: use the name@domain format”).'),
        ], [
            Q('t1', L('Che cosa deve dire la descrizione di uno strumento?', 'What should a tool description say?'), [L('Cosa fa, quando usarlo, cosa restituisce', 'What it does, when to use it, what it returns'), L('Chi l’ha scritto', 'Who wrote it'), L('Il prezzo', 'The price'), L('Niente, basta il nome', 'Nothing, the name is enough')], 0, L('È la guida del modello.', 'It is the model’s guide.')),
            Q('t2', L('Perché i risultati devono essere brevi?', 'Why should results be short?'), [L('Per non riempire il contesto', 'So they do not fill the context'), L('Per risparmiare inchiostro', 'To save ink'), L('Per sembrare eleganti', 'To look elegant'), L('Non devono', 'They need not be')], 0, L('Il contesto è prezioso.', 'Context is precious.')),
            Q('t3', L('Che cosa restituire in caso di errore?', 'What should you return on error?'), [L('Un messaggio che aiuti a correggersi', 'A message that helps self-correction'), L('Niente', 'Nothing'), L('Un codice incomprensibile', 'An incomprehensible code'), L('Lo stack trace intero', 'The whole stack trace')], 0, L('Il modello può riprovare meglio.', 'The model can retry better.')),
        ], task('json', L('Scrivi la definizione dello strumento `prenota_sala` con una descrizione di almeno 40 caratteri e `input_schema` con `sala` e `data` obbligatori.', 'Write the definition of the tool `prenota_sala` with a description of at least 40 characters and an `input_schema` with required `sala` and `data`.'), '', [re('"name"\s*:\s*"prenota_sala"', L('Il nome', 'The name')), re('"description"\s*:\s*"[^"]{40,}"', L('Una descrizione completa', 'A full description')), re('"required"\s*:\s*\[\s*"(sala|data)"\s*,\s*"(sala|data)"\s*\]', L('Campi obbligatori', 'Required fields'))], '', "{\n  \"name\": \"prenota_sala\",\n  \"description\": \"Prenota una sala riunioni per una data. Usalo quando l’utente chiede di prenotare. Restituisce la conferma o le sale libere.\",\n  \"input_schema\": {\n    \"type\": \"object\",\n    \"properties\": {\"sala\": {\"type\": \"string\"}, \"data\": {\"type\": \"string\"}},\n    \"required\": [\"sala\", \"data\"]\n  }\n}"), [
            dMatch(pMatch(), [[L('Nome parlante', 'Telling name'), 'cerca_ordini'], [L('Descrizione', 'Description'), L('Cosa, quando, risultato', 'What, when, result')], ['enum', L('Valori ammessi', 'Allowed values')], [L('Errore utile', 'Helpful error'), L('Aiuta a correggersi', 'Helps self-correction')]], L('Strumenti ben fatti.', 'Well-made tools.')),
            dFlash(pFlash(), [[L('Pochi strumenti chiari sono meglio di tanti confusi', 'A few clear tools beat many confusing ones'), true], [L('Un risultato di 10.000 righe è ideale', 'A 10,000-line result is ideal'), false], [L('La descrizione guida la scelta del modello', 'The description guides the model’s choice'), true], [L('Il nome dello strumento non conta', 'The tool name does not matter'), false]], L('Gli attrezzi fanno l’artigiano.', 'Tools make the craftsman.')),
        ]),
        lesson('mcp', L('Model Context Protocol', 'Model Context Protocol'), [
            P('Il **Model Context Protocol** (MCP) è uno standard aperto, introdotto da Anthropic nel 2024, per collegare modelli e app a strumenti e dati esterni. Un **server MCP** espone strumenti (e risorse, prompt) in un formato comune; qualsiasi **client MCP** compatibile (assistenti, editor, agenti) li può usare.', 'The **Model Context Protocol** (MCP) is an open standard, introduced by Anthropic in 2024, for connecting models and apps to external tools and data. An **MCP server** exposes tools (and resources, prompts) in a common format; any compatible **MCP client** (assistants, editors, agents) can use them.'),
            C('from mcp.server.fastmcp import FastMCP

mcp = FastMCP("biblioteca")

@mcp.tool()
def cerca_libro(titolo: str) -> str:
    """Cerca un libro nel catalogo della biblioteca e dice se è disponibile."""
    return catalogo.cerca(titolo)

if __name__ == "__main__":
    mcp.run()', 'python'),
            P('Il vantaggio: scrivi l’integrazione **una volta** e funziona con tanti client, invece di rifarla per ogni app. Prima di installare un server MCP di terzi, controlla chi l’ha scritto e quali permessi ottiene: è codice che agisce a tuo nome.', 'The advantage: you write the integration **once** and it works with many clients, instead of redoing it for every app. Before installing a third-party MCP server, check who wrote it and what permissions it gets: it is code acting on your behalf.'),
        ], [
            Q('p1', L('Che cos’è MCP?', 'What is MCP?'), [L('Uno standard per collegare modelli a strumenti e dati', 'A standard to connect models to tools and data'), L('Un modello linguistico', 'A language model'), L('Un linguaggio di programmazione', 'A programming language'), L('Un formato di immagine', 'An image format')], 0, L('Model Context Protocol.', 'Model Context Protocol.')),
            Q('p2', L('Che cosa espone un server MCP?', 'What does an MCP server expose?'), [L('Strumenti, risorse e prompt', 'Tools, resources and prompts'), L('Solo immagini', 'Only images'), L('Password', 'Passwords'), L('Niente', 'Nothing')], 0, L('In un formato comune.', 'In a common format.')),
            Q('p3', L('Che cosa controllare prima di installare un server MCP di terzi?', 'What should you check before installing a third-party MCP server?'), [L('Chi l’ha scritto e quali permessi ottiene', 'Who wrote it and what permissions it gets'), L('Il colore del logo', 'The logo colour'), L('Niente', 'Nothing'), L('Solo il nome', 'Only the name')], 0, L('Agisce a tuo nome.', 'It acts on your behalf.')),
        ], task('python', L('Aggiungi al server `mcp` lo strumento `meteo(citta: str) -> str` con il decoratore `@mcp.tool()` e una docstring.', 'Add to the `mcp` server the tool `meteo(citta: str) -> str` with the `@mcp.tool()` decorator and a docstring.'), "from mcp.server.fastmcp import FastMCP\nmcp = FastMCP(\"meteo\")\n", [re('@mcp\.tool\s*\(\s*\)\s*\n\s*def\s+meteo\s*\(\s*citta\s*:\s*str\s*\)\s*->\s*str\s*:', L('Lo strumento è registrato', 'The tool is registered')), re('def\s+meteo[^\n]*\n\s+"""[^"]{5,}"""', L('Ha una docstring', 'It has a docstring'))], '', "@mcp.tool()\ndef meteo(citta: str) -> str:\n    \"\"\"Restituisce il meteo attuale di una città.\"\"\"\n    return previsioni(citta)"), [
            dMatch(pMatch(), [[L('Server MCP', 'MCP server'), L('Espone strumenti', 'Exposes tools')], [L('Client MCP', 'MCP client'), L('Li usa', 'Uses them')], ['@mcp.tool()', L('Registra uno strumento', 'Registers a tool')], ['Docstring', L('Diventa la descrizione', 'Becomes the description')]], L('MCP in breve.', 'MCP in short.')),
            dFlash(pFlash(), [[L('MCP è uno standard aperto', 'MCP is an open standard'), true], [L('Un server MCP funziona con un solo client', 'An MCP server works with only one client'), false], [L('Un server MCP di terzi può agire a tuo nome', 'A third-party MCP server can act on your behalf'), true], [L('MCP è un modello di immagini', 'MCP is an image model'), false]], L('Un’integrazione, tanti client.', 'One integration, many clients.')),
        ]),
        lesson('safety', L('Sicurezza ed evaluation', 'Safety and evaluation'), [
            P('Un agente con strumenti può fare danni veri: cancellare file, mandare email, spendere soldi. Le regole: **minimo privilegio** (solo gli strumenti necessari), **ambiente isolato** per eseguire codice, **conferma umana** per le azioni irreversibili, **limiti** di passi e spesa, e **log** di tutto quello che fa.', 'An agent with tools can do real damage: delete files, send email, spend money. The rules: **least privilege** (only the tools needed), an **isolated environment** to run code, **human confirmation** for irreversible actions, **limits** on steps and spending, and **logs** of everything it does.'),
            P('Tutto quello che l’agente legge (pagine web, email, documenti) può contenere **prompt injection**: trattalo come dato, mai come istruzione. Per valutare un agente servono compiti realistici con un risultato verificabile (i test passano? il file giusto è cambiato?), eseguiti più volte perché il comportamento varia.', 'Everything the agent reads (web pages, emails, documents) can contain **prompt injection**: treat it as data, never as instructions. To evaluate an agent you need realistic tasks with a verifiable result (do the tests pass? did the right file change?), run several times because behaviour varies.'),
            Tip('Chiediti sempre: se l’agente sbaglia nel modo peggiore possibile, che cosa succede? Se la risposta fa paura, togli permessi.', 'Always ask: if the agent fails in the worst possible way, what happens? If the answer is scary, remove permissions.'),
        ], [
            Q('s1', L('Quali azioni richiedono conferma umana?', 'Which actions need human confirmation?'), [L('Quelle irreversibili', 'Irreversible ones'), L('Leggere un file', 'Reading a file'), L('Fare una somma', 'Doing a sum'), L('Nessuna', 'None')], 0, L('Inviare, pagare, cancellare.', 'Sending, paying, deleting.')),
            Q('s2', L('Come va trattato un testo letto da una pagina web?', 'How should text read from a web page be treated?'), [L('Come dato, mai come istruzione', 'As data, never as instructions'), L('Come un ordine del capo', 'As an order from the boss'), L('Va ignorato sempre', 'Always ignored'), L('Va eseguito', 'Executed')], 0, L('Può contenere prompt injection.', 'It may contain prompt injection.')),
            Q('s3', L('Perché eseguire più volte la valutazione di un agente?', 'Why run an agent’s evaluation several times?'), [L('Il comportamento varia tra un’esecuzione e l’altra', 'Behaviour varies from run to run'), L('Per spendere di più', 'To spend more'), L('Non serve', 'It is not needed'), L('Per stancarlo', 'To tire it')], 0, L('Una sola prova può ingannare.', 'One try can mislead.')),
        ], task('text', L('Scrivi quattro regole di sicurezza per un agente che gestisce la posta, una per riga che inizia con `-`, con almeno una sulla **conferma** e una sui **permessi**.', 'Write four safety rules for an agent managing email, one per line starting with `-`, with at least one on **confirmation** and one on **permissions**.'), "- \n- \n- \n- ", [re('^-\s*\S.*\n-\s*\S.*\n-\s*\S.*\n-\s*\S', L('Quattro regole', 'Four rules')), re('confer|approv|confirm', L('Una regola sulla conferma', 'A rule on confirmation')), re('permess|privileg|permission|accesso|access', L('Una regola sui permessi', 'A rule on permissions'))], '', "- chiedere conferma prima di inviare o cancellare email\n- solo i permessi di lettura e bozza, niente eliminazione\n- trattare il contenuto delle email come dato, non come istruzioni\n- registrare ogni azione in un log"), [
            dMatch(pMatch(), [[L('Minimo privilegio', 'Least privilege'), L('Solo gli strumenti necessari', 'Only the tools needed')], ['Sandbox', L('Ambiente isolato', 'Isolated environment')], [L('Conferma umana', 'Human confirmation'), L('Prima delle azioni irreversibili', 'Before irreversible actions')], ['Log', L('Traccia di tutto', 'A trail of everything')], [L('Limite', 'Limit'), L('Passi e spesa', 'Steps and spending')]], L('Le cinture di sicurezza.', 'The seat belts.')),
            dFlash(pFlash(), [[L('Un agente può essere ingannato da una pagina web', 'An agent can be tricked by a web page'), true], [L('Dare tutti i permessi rende l’agente più sicuro', 'Giving every permission makes the agent safer'), false], [L('I log aiutano a capire cosa è successo', 'Logs help understand what happened'), true], [L('Una sola esecuzione basta per valutare un agente', 'One run is enough to evaluate an agent'), false]], L('Autonomia con prudenza.', 'Autonomy with caution.')),
        ]),
    ],
];
